insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('business-toyota-production', '00000000-0000-4000-8000-000000000001', 'トヨタ生産方式の進化', '1930年代の豊田自動織機の自動車部から2020年代の半導体不足まで、トヨタ生産方式（TPS）を生産技術と現場・経営と危機・世界への波及の3層で辿る。危機のたびに現場の手法が磨かれた過程が見える。', 'business', 'ja', 'public', 's_business-toyota-production', 1933, 2022, 'business-toyota-production')
