insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('history-space-race', '00000000-0000-4000-8000-000000000001', '宇宙開発の舞台裏', 'スプートニクから民間宇宙船まで、ロケットの進歩だけでなく、その裏で誰が何を決め、社会がどう反応したかを三層で重ねる。同じ年に別の場所で起きていたことが見えてくる年表。', 'history-politics', 'ja', 'public', 's_history-space-race', 1957, 2020, 'history-space-race')
on conflict (slug) do update set title = excluded.title, description = excluded.description, category = excluded.category,
  start_year = excluded.start_year, end_year = excluded.end_year, updated_at = now();
delete from public.layers where timeline_id = (select id from public.timelines where slug = 'history-space-race');
delete from public.events where timeline_id = (select id from public.timelines where slug = 'history-space-race');
