insert into public.timelines (slug, owner_id, title, description, category, language, visibility, share_id, start_year, end_year, cover_seed)
values ('tech-mobile-revolution', '00000000-0000-4000-8000-000000000001', 'モバイル革命の全体像', 'iモードのモバイルネットからiPhone登場、アプリ経済圏の拡大、そして巨大プラットフォームへの規制まで。端末技術・アプリとビジネス・社会と制度の3層で、スマートフォンが生活の基盤になるまでを追う。', 'technology', 'ja', 'public', 's_tech-mobile-revolution', 1999, 2026, 'tech-mobile-revolution')
